@Configuration
public class HaloConfig {

    @Bean
    public String salam() {
        System.out.println("Membuat bean salam");
        return "Halo dari Spring!";
    }
}

public class HaloApp {
    public static void main(String[] args) {
        System.out.println("Mulai");
        var context = new AnnotationConfigApplicationContext(HaloConfig.class);
        System.out.println(context.getBean(String.class));
        context.close();
        System.out.println("Selesai");
    }
}

